"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:1":{"b": ["برندیزی از دوک‌نشین آپولیا به پادشاهی سیسیل رسید (روجرو دوم)", "6519178f"], "d": ["روجرو دوم در 1128 برندیزی را در شاهزاده‌نشین تارانتوی بوهموند دوم گرفت (ثانویه)؛ همان روز زنجیره‌های باری و سالرنو.", "7adade28"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:2":{"b": ["لچه از دوک‌نشین آپولیا به پادشاهی سیسیل رسید (روجرو دوم؛ مرکز برادر بزرگ‌تر باری)", "22cdacd2"], "d": ["لچه با پیوستن دوک‌نشین آپولیا به پادشاهی سیسیل (1128) وابسته به زنجیرهٔ باری دست‌به‌دست شد؛ جملهٔ تاریخ‌دار ویژهٔ شهر یافت نشد.", "9c938986"]},
