"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:4":{"b": ["رجو کالابریا از دوک‌نشین آپولیا و کالابریا به پادشاهی سیسیل رسید (روجرو دوم)", "37e6922f"], "d": ["کالابریا با رسیدن دوک‌نشین آپولیا و کالابریا به روجر دوم (1128) بخشی از پادشاهی سیسیل شد؛ جملهٔ تاریخ‌دار ویژهٔ شهر یافت نشد (مرکز برادر بزرگ‌تر، زنجیرهٔ باری/ملفی).", "e8b41ab1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1143-01-01:0":{"b": ["کمون رم تأسیس شد: سنا نوسازی شد (renovatio senatus)، حاکمیت دنیوی پاپ معلق شد", "b54d2c34"], "d": ["مردم رم کمون و سنا را در کاپیتول از نو برپا کردند؛ با تأثیر آرنالدو دا برشا تا 1155 حاکمیت پاپی عملاً به رسمیت شناخته نشد (künye f 1143، Treccani 1144).", "baeccd38"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1283-01-01:0":{"b": ["رجو کالابریا از آنژو به آراگون-سیسیل رسید (پدرو سوم در کالابریا پیاده شد)", "800b47b1"], "d": ["پس از شام سیسیلی (1282)، رجو در دست آنژو ماند؛ در آغاز 1283 پدرو سوم، پادشاه آراگون، در کالابریا پیاده شد و رجو پایگاه آراگونی جنگ علیه آنژوها گردید (در ژوئیهٔ 1284 شارل دانژو شهر را محاصره کرد اما نتوانست بگیرد). روز در منبع نیست، در سطح سال.", "6b2afca7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1302-08-31:0":{"b": ["صلح کالتابلوتا: رجو کالابریا از آراگون-سیسیل به آنژو (ناپل) بازگشت", "241c90a7"], "d": ["صلح کالتابلوتا (31 اوت 1302) به معنای چشم‌پوشی فدریکو سوم از املاک کالابریای سرزمین اصلی و ماندن جزیره به‌عنوان پادشاهی تری‌ناکریا در شاخهٔ آراگون بود؛ رجو به پادشاهی ناپل آنژو رسید.", "c2a155cb"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1318-07-25:0":{"b": ["یاکوپو یکم دا کارارا حامی و والی پادوا برگزیده شد: کمون پادوا به یک سنیور رسید", "b3fc0eae"], "d": ["اشرافیت پادوا یاکوپو یکم دا کارارا را مادام‌العمر حامی/والی برگزید (اندکی پس از 25 ژوئیه 1318)؛ کمون به یک سنیور واگذار شد. روز قطعی نیست، نخستین روز بازه گرفته شد.", "aa9a4a3f"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1351-05-01:0":{"b": ["زوریخ با اتحاد ابدی به کنفدراسیون پیوست: پنجمین عضو پس از لوتسرن، اوری، شویتس و اونترفالدن", "78e9419b"], "d": ["زوریخ در 1 مه 1351 با لوتسرن، اوری، شویتس و اونترفالدن اتحاد ابدی بست و عضو کنفدراسیون کهن سوئیس شد.", "4646e7ae"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1399-01-01:0":{"b": ["پیزا به جان گالئاتسو ویسکونتی فروخته شد (جرارد آپیانو)", "eba05ce2"], "d": ["سنیوری خاندان آپیانو در پیزا به دست جرارد به جان گالئاتسو ویسکونتی، دوک میلان، فروخته شد؛ پیزا در 1399-1402 وابسته به دوک‌نشین میلان ماند. روز در منبع نیست (در سطح سال 1399).", "705f44b2"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1402-09-03:0":{"b": ["جان گالئاتسو ویسکونتی درگذشت: پیزا از میلان جدا شد و زیر گابریله ماریا ویسکونتی مستقل ماند", "9e80b0ad"], "d": ["با مرگ جان گالئاتسو (سپتامبر 1402) پیزا بر پایهٔ وصیت به پسر نامشروعش گابریله ماریا ویسکونتی رسید؛ Treccani EI و SNS این را استقلال کوتاه‌مدت پیزا روایت می‌کنند. گابریله ماریا در 27 اوت 1405 حقوق خود را به فلورانس فروخت و شهر در اکتبر 1406 فتح شد.", "e34aec85"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1506-11-11:0":{"b": ["پاپ ژولیوس دوم وارد بولونیا شد: سنیوری بنتیوولیو برچیده شد، پاپ اداره مستقیم را آغاز کرد", "dc4823a7"], "d": ["پاپ ژولیوس دوم با سپاه خود وارد بولونیا شد و جووانی دوم بنتیوولیو را بیرون راند؛ شهر به دولت پاپی پیوست.", "9afc6459"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1532-01-01:0":{"b": ["آزادی کمون آنکونا پایان یافت: با کلمنت هفتم مستقیماً به حاکمیت پاپی درآمد", "d2fbbb8f"], "d": ["آزادی کمونی جمهوری آنکونا در 1532 در دوران کلمنت هفتم با درآمدن به حاکمیت مستقیم دولت پاپی پایان یافت (دقت سال؛ روز/ماه خوانده نشد).", "518c4913"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1536-05-21:0":{"b": ["ژنو به اصلاحات رأی داد: سلطهٔ اسقف و ساووا پایان یافت، جمهوری ژنو پدید آمد", "dcb02e44"], "d": ["ژنو با رأی‌گیری مجمع عمومی در 21 مه 1536 اصلاح دینی را پذیرفت؛ شهر به‌عنوان جمهوری مستقل در کنار برن ماند اما عضو کنفدراسیون نشد.", "fd9e9db5"]},
