"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1057-03-10:0":{"b": ["امیر زیری معز از قیروان رفت و به مهدیه رفت؛ قیروان به دست هلالیان افتاد", "becee655"], "d": ["با محاصرهٔ بنی‌هلال، معز بن بادیس در سال 449 (1057) از قیروان رفت و به مهدیه که پسرش تمیم والی آن بود رفت؛ قیروانِ بی‌دفاع به دست بیابان‌نشینان غارت و سوزانده شد.", "7b6732bb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1061-01-01:0":{"b": ["کنت روژه مسینا را گرفت (1061)", "28b31d9a"], "d": ["روژه در 1061 به پیرامون مسینا پیاده شد و شهر را نسبتاً آسان گرفت؛ بدین‌سان فتح نورمن سیسیل آغاز شد. TDV این سال را سال گرفته‌شدن مسینا می‌دهد.", "d06afdbf"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1067-01-01:0":{"b": ["آلب‌ارسلان قارص بیزانس را فتح کرد؛ پادشاه گرجی مطیع سلجوقیان شد", "25994288"], "d": ["آلب‌ارسلان در 1067 دوباره در مرزهای بیزانس و گرجستان پدیدار شد؛ قارصِ وابسته به بیزانس فتح شد و پادشاه گرجی مطیع سلجوقیان شد.", "5395feca"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1067-01-01:1":{"b": ["آلب‌ارسلان قیصریه را گرفت", "c40df514"], "d": ["در زمان آلب‌ارسلان، سلطان سلجوقی، ترکان در 1065 آنی و در 1067 قیصریه را گرفتند؛ بیزانس دروازه‌های کاپادوکیه را از دست داد.", "fbeb3963"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1071-01-01:0":{"b": ["کاتانیا به دست نورمن‌ها افتاد (1071)", "21617f1b"], "d": ["در حالی که محاصرهٔ باری ادامه داشت، در 1071 کاتانیا با خیانتی در شهر به دست نورمن‌ها افتاد؛ اما شهر بعد از دست رفت و حدود ده سال بعد برای همیشه گرفته شد.", "3d49a9a2"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1072-01-01:0":{"b": ["مازارا به دست نورمن‌ها افتاد (1072)", "e7cb9667"], "d": ["در 1072، سالی که پالرمو گرفته شد، مازارا نیز فتح شد؛ در سال‌های بعد در آنجا دژ ساخته شد تا در برابر حمله‌ای با ریشهٔ شمال آفریقا ایستادگی شود (1075).", "95450106"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1072-12-15:0":{"b": ["نصر دوم با مرگ آلب‌ارسلان ترمذ را گرفت، سپس به بلخ لشکر کشید و آن را نیز گرفت", "7747ccc9"], "d": ["با مرگ آلب‌ارسلان در لشکرکشی ماوراءالنهر، شمس‌الملک نصر دوم، قراخانی باختری، در ربیع‌الآخر 465 (دسامبر 1072) ترمذ را گرفت، سپس به بلخ لشکر کشید و آن را نیز گرفت؛ ستیز سلجوقی-قراخانی در دورهٔ ملکشاه ادامه یافت.", "1ba5253a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1073-01-01:0":{"b": ["آمالفی در برابر فشار سالرنو به روبرتو ایل گویسکاردو روی می‌آورد؛ نورمن‌ها شهر را اشغال می‌کنند و استقلال...", "3d375631"], "d": ["آمالفی در برابر فشار سالرنو به روبرتو ایل گویسکاردو روی می‌آورد؛ نورمن‌ها شهر را اشغال می‌کنند و استقلال پایان می‌یابد.", "be93237a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1075-08-16:0":{"b": ["ساوتکین، امیر ملکشاه، ارّان را گرفت؛ شاخهٔ گنجهٔ شدادیان پایان یافت", "e031fc26"], "d": ["در زمان فضل سوم شدادی، ساوتکین، از امیران سلطان ملکشاه، ارّان را گرفت (468/1075-76)؛ ناحیه زیر اداره سلجوقی درآمد و شاخهٔ گنجهٔ شدادیان پایان یافت.", "b39c17bd"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1076-01-01:0":{"b": ["سالرنو به روبرت گویسکارد افتاد؛ شاهزادهنشین لومبارد سالرنو پایان یافت", "c678238f"], "d": ["پس از ایستادگی طولانی، سالرنو در دسامبر 1076 به روبرت گویسکارد تسلیم شد؛ شاهزاده گیسولف دوم به تبعید رفت و به دربار پاپ پناه برد. گویسکارد سالرنو را پایتخت دوکنشین خود ساخت.", "705fecee"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1077-01-01:0":{"b": ["روژه با ناوگان خود تراپانی را گرفت", "2b0b3d98"], "d": ["روژه که ناوگانی بنیان نهاده بود، در 1077 فعالیت جنگی را شدت بخشید، تراپانی و سپس کاسترونوو را گرفت.", "6e482ca5"]},
