"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1081-01-01:0":{"b": ["روبرت گویسکارد در والونا پیاده شد و کورفو را گرفت", "d5e43c94"], "d": ["در 1081 گویسکارد با ناوگان خود به والونا (آولونیا) رفت، کورفو را گرفت و در 1082 دوراتزو را به چنگ آورد؛ لشکرکشی به استانبول با فراخوان یاری گرگوریوس هفتم در روم نیمه‌تمام ماند.", "f805ca31"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1082-01-01:0":{"b": ["سلیمان‌شاه یکم، بنیان‌گذار سلجوقیان آناتولی، طرسوس را فتح کرد", "93d6092f"], "d": ["سلیمان‌شاه یکم در 475/1082 طرسوس را فتح کرد؛ شهر در 490/1097 به دست صلیبیان گرفته شد و سپس میان صلیبیان، بیزانس و ارمنیان منطقه دست‌به‌دست شد.", "912208e8"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1084-03-24:0":{"b": ["روم به هانری چهارم تسلیم می‌شود؛ ضدپاپ کلمنس سوم (گیبر) بر تخت نشانده می‌شود، هانری تاج امپراتوری بر سر می‌نهد، گرگوریوس از روم می‌گریزد", "311cfeb4"], "d": ["رومیان شهر را به هانری که در 1081 به ایتالیا فرود آمده بود، تسلیم کردند؛ گیبر، اسقف اعظم راونا، در 24 مارس 1084 با نام کلمنس سوم پاپ اعلام شد و هانری را پاپ رقیب امپراتور تاج‌گذاری کرد. گرگوریوس هفتم که سیزده کاردینال او را رها کرده بودند، ناچار از روم گریخت؛ بر پشتیبانی نورمن‌ها تکیه کرد.", "996d4e46"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1084-05-10:0":{"b": ["مرابطان بر سبته (سئوتا) چیره شدند", "48f062fb"], "d": ["یوسف بن تاشفین در سال 477 (1084) سبته (سئوتا) را زیر فرمان گرفت؛ این دروازهٔ گذر به اندلس شد.", "4ba802e3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1085-01-01:0":{"b": ["بلداجی، امیر سلیمان‌شاه، ناحیهٔ جیحان (البستان) را فتح کرد", "406d5385"], "d": ["ناحیهٔ جیحان (البستان) که هدف هجوم غازیان ترکمن بود، در 1085 به دست بلداجی، از امیران سلیمان‌شاه، سلطان سلجوقیان آناتولی، فتح شد.", "f1f8ec8c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1086-01-01:0":{"b": ["سیراکوز به نورمن‌ها افتاد", "0d66d006"], "d": ["پس از سقوط آگریجنتو در ژوئیه 1086، در اکتبر 1086 سیراکوز به دست نورمن‌ها افتاد؛ کاستروجووانی در 1087 و نوتو در 1091 تسلیم خواهند شد.", "b99596a6"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1086-07-11:0":{"b": ["تتش پس از مدتی محاصرهٔ حلب آن را گرفت.", "11f90dba"], "d": ["تتش پس از مدتی محاصرهٔ حلب آن را گرفت.", "11f90dba"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1088-03-27:0":{"b": ["ملکشاه بخارا و سمرقند را گرفت و احمدخان قراخانی باختری را اسیر کرد و به اصفهان برد", "ababb7d4"], "d": ["با کشته‌شدن قاضی‌القضات احمد بن سلیمان به دست احمدخان و با فراخوان یاری فقیه شافعی ابوطاهر بن علک، ملکشاه در 481 (1088) بخارا و سمرقند را گرفت و به اوزکند آمد؛ احمدخان را اسیر کرد و به اصفهان برد. در سمرقند ابوطاهر خوارزمی به نیابت گماشته شد.", "b43535bd"]},
